<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue'
import {RouterLink,useRoute} from 'vue-router'
import StatePanel from '../components/StatePanel.vue'
import {getDataOverview,getNewPapers,type DataOverview,type NewPapers} from '../services/admin.ts'
const route=useRoute()
const overview=ref<DataOverview|null>(null),days=ref(14),loading=ref(false),error=ref('')
const selectedDate=ref(''),daily=ref<NewPapers|null>(null),dayError=ref(''),dayLoading=ref(false),page=ref(1)
let version=0,dayVersion=0
const number=(n:number|null|undefined)=>n==null?'—':n.toLocaleString('zh-CN')
const sourceName=(s:string)=>({openalex:'OpenAlex',ecva:'ECVA',cvf:'CVF',dblp:'DBLP',unknown:'待核对'} as Record<string,string>)[s]??s
const addedCount=(point:DataOverview['trend'][number])=>point.added_papers??point.papers
const max=computed(()=>Math.max(1,...(overview.value?.trend??[]).map(addedCount)))
const maxWithdrawn=computed(()=>Math.max(1,...(overview.value?.trend??[]).map(p=>p.withdrawn_papers??0)))
const chartScale=computed(()=>206/(max.value+maxWithdrawn.value))
const positiveHeight=computed(()=>max.value*chartScale.value)
const negativeHeight=computed(()=>maxWithdrawn.value*chartScale.value)
const methods=[{key:'manual',label:'手动导入'},{key:'automatic',label:'自动采集'}] as const
const modeCount=(point:DataOverview['trend'][number],key:'manual'|'automatic')=>(point.added_import_modes??point.import_modes)?.[key]??(key==='automatic'?addedCount(point):0)
const sourceKeys=computed(()=>overview.value?.source_summary.map(s=>s.name)??[])
async function load(){const v=++version;loading.value=true;error.value='';try{const value=await getDataOverview(days.value);if(v===version)overview.value=value}catch(e){if(v===version)error.value=e instanceof Error?e.message:'数据读取失败'}finally{if(v===version)loading.value=false}}
async function showDay(date:string,next=1){const v=++dayVersion;selectedDate.value=date;page.value=next;daily.value=null;dayLoading.value=true;dayError.value='';try{const value=await getNewPapers(date,next);if(v===dayVersion)daily.value=value}catch(e){if(v===dayVersion)dayError.value=e instanceof Error?e.message:'论文读取失败'}finally{if(v===dayVersion)dayLoading.value=false}}
watch(days,()=>{selectedDate.value='';dayVersion++;void load()});onMounted(load)
</script>
<template>
<section class="standard-page data-overview">
<div class="page-heading overview-heading"><div><div class="eyebrow">DATA MANAGEMENT</div><h1>数据概览</h1><p>查看论文收录、每日新增和导入进度。</p></div><div class="heading-actions"><button class="button button-secondary" :disabled="loading" @click="load">刷新</button><RouterLink class="button button-secondary" to="/admin/jobs">批次对比</RouterLink><RouterLink class="button button-primary" to="/admin/imports">导入论文</RouterLink></div></div>
<div v-if="overview?.demo_mode" class="demo-notice"><span v-if="route.query.preview==='clean-v2'" class="preview-version">新版预览 · </span>演示环境 · 使用真实论文，初始日期与自动采集为模拟展示</div>
<StatePanel v-if="loading&&!overview" kind="loading" title="正在读取数据"/><StatePanel v-else-if="error" kind="error" title="数据读取失败" :description="error" retry @retry="load"/>
<template v-else-if="overview">
<div class="metric-grid"><article class="metric-card"><div class="metric-top">有效论文总数</div><strong>{{number(overview.total_papers)}}</strong><div class="metric-bottom">已去重并排除目录等非论文内容</div></article><article class="metric-card"><div class="metric-top">今日新增</div><strong>{{number(overview.today_added_papers??overview.today_papers)}}</strong><div class="metric-bottom">今日撤回 {{overview.today_withdrawn_papers??0}} 篇 · 净增 {{overview.today_net_papers??overview.today_papers}} 篇</div></article><article class="metric-card"><div class="metric-top">摘要完整率</div><strong>{{overview.total_papers?Math.round(overview.with_abstract/overview.total_papers*1000)/10:0}}<small>%</small></strong><div class="metric-bottom">{{number(overview.with_abstract)}} / {{number(overview.total_papers)}} 篇含摘要</div></article></div>
<div class="layout-grid"><section class="panel chart-panel"><header class="card-heading"><div><h2>每日新增与撤回</h2><p>上方为新增，下方橙色为撤回；点击日期查看明细</p></div><div class="period-switch"><button v-for="n in [7,14]" :key="n" :class="{active:days===n}" @click="days=n">{{n}} 天</button></div></header>
<div class="trend-chart"><div class="chart-guides"><span>{{number(max)}}</span><span class="zero-label" :style="{top:`${positiveHeight-6}px`}">0</span><span v-if="overview.trend.some(point=>point.withdrawn_papers)" class="negative-label" :style="{top:`${positiveHeight+negativeHeight-6}px`}">−{{number(maxWithdrawn)}}</span></div><div class="chart-bars"><button v-for="point in overview.trend" :key="point.date" class="bar-column" :title="`${point.date}：新增 ${addedCount(point)} 篇，手动 ${modeCount(point,'manual')} 篇，自动 ${modeCount(point,'automatic')} 篇；撤回 ${point.withdrawn_papers??0} 篇（${point.withdrawn_batches??0} 批）`" @click="showDay(point.date)"><div class="positive-zone" :style="{height:`${positiveHeight}px`}"><div class="source-stack" :style="{height:`${addedCount(point)/max*100}%`}"><i v-for="method in methods" :key="method.key" :class="`mode-${method.key}`" :style="{height:`${modeCount(point,method.key)/Math.max(1,addedCount(point))*100}%`}"/></div></div><div class="negative-zone" :style="{height:`${negativeHeight+14}px`}"><i v-if="point.withdrawn_batches" class="withdraw-stack mode-withdrawal" :style="{height:`${Math.max(3,(point.withdrawn_papers??0)*chartScale)}px`}"/><small v-if="point.withdrawn_batches" class="withdraw-value" :style="{top:`${Math.max(3,(point.withdrawn_papers??0)*chartScale)+1}px`}">{{point.withdrawn_papers?`−${point.withdrawn_papers}`:`${point.withdrawn_batches}批`}}</small></div><span class="bar-date">{{point.date.slice(5)}}</span></button></div></div><div class="chart-foot"><span v-for="method in methods" :key="method.key"><i class="method-marker" :class="`mode-${method.key}`"/>{{method.label}}</span><span><i class="method-marker mode-withdrawal"/>撤回论文</span></div>
</section><section class="panel chart-panel source-panel"><header class="card-heading"><div><h2>数据来源</h2><p>每篇论文归属一个主要采集来源</p></div></header><div class="source-cards"><article v-for="source in overview.source_summary" :key="source.name"><div class="source-card-top"><span><i class="source-marker" :class="`source-${sourceKeys.indexOf(source.name)%4}`"/>{{sourceName(source.name)}}</span><strong>{{number(source.papers)}} <small>篇</small></strong></div><div class="source-track"><div class="source-fill" :class="`source-${sourceKeys.indexOf(source.name)%4}`" :style="{width:`${source.papers/Math.max(1,overview.total_papers)*100}%`}"/></div><p>最近导入 <time>{{source.last_imported_at?.slice(0,16).replace('T',' ')??'待核对'}}</time></p></article></div><div class="meeting-tags"><span v-for="venue in overview.venues" :key="venue.name">{{venue.name}} <b>{{number(venue.papers)}}</b></span></div></section></div>
<section v-if="selectedDate" class="panel chart-panel day-detail"><header><strong>{{selectedDate}} · 新增 {{dayLoading?'读取中':daily?.total??'—'}} 篇 · 撤回 {{daily?.withdrawn_papers??0}} 篇</strong><button class="text-button" @click="selectedDate='';dayVersion++">收起</button></header><p v-if="dayLoading">正在读取…</p><p v-else-if="dayError" class="inline-error">{{dayError}}</p><template v-else-if="daily"><h3 class="day-section-heading">新增论文</h3><p v-if="!daily.total" class="inline-note">当天没有新增论文。</p><div v-for="(paper,index) in daily.items" :key="`${paper.id}-${paper.batch_id??index}`" class="day-paper"><span>{{paper.title}}</span><small>{{paper.venue}} {{paper.year}}</small></div><div v-if="daily.total>10" class="day-pages"><button class="text-button" :disabled="page<=1" @click="showDay(selectedDate,page-1)">上一页</button><span>第 {{page}} 页</span><button class="text-button" :disabled="page*10>=daily.total" @click="showDay(selectedDate,page+1)">下一页</button></div><section class="day-withdrawals" aria-label="当日撤回记录"><h3 class="day-section-heading">撤回记录 · {{daily.withdrawals?.length??0}} 批</h3><p v-if="!daily.withdrawals?.length" class="inline-note">当天没有批次撤回。</p><article v-for="item in daily.withdrawals" :key="item.batch_id" class="withdrawal-event"><div><strong>{{item.display_code??item.batch_code}}</strong><span>退出论文库 {{item.removed_papers}} 篇 · 其他批次仍提供 {{item.retained_papers}} 篇</span></div><p>{{item.reason}}</p><RouterLink class="text-button" :to="{path:'/admin/jobs',query:{job_id:String(item.batch_id)}}">查看撤回批次 →</RouterLink></article></section></template></section>
<section class="panel chart-panel recent-section"><header class="card-heading"><div><h2>最新导入论文</h2><p>按首次导入时间排列，点击标题打开论文主页</p></div><span class="recent-count">最近 20 篇</span></header><div class="table-scroll"><table class="latest-table"><thead><tr><th>论文标题 / 作者</th><th>会议</th><th>导入时间</th></tr></thead><tbody><tr v-for="paper in overview.latest_papers" :key="paper.id"><td><strong><a v-if="paper.homepage_url" :href="paper.homepage_url" target="_blank" rel="noopener noreferrer" :aria-label="`打开论文主页：${paper.title}`">{{paper.title}} ↗</a><span v-else>{{paper.title}}</span></strong><small>{{paper.authors.slice(0,3).join('、')||'作者信息暂缺'}}{{paper.authors.length>3?' 等':''}}</small></td><td><span class="paper-venue">{{paper.venue}} {{paper.year}}</span></td><td>{{paper.imported_at.slice(0,16).replace('T',' ')}}</td></tr></tbody></table><p v-if="!overview.latest_papers.length" class="inline-note">还没有导入论文。</p></div></section>
</template></section>
</template>
<style scoped>
